type Priority = "low" | "normal" | "high";
interface NewTask {
  title: string;
  priority: Priority;
}
const PRIORITIES: readonly Priority[] = ["low", "normal", "high"];

function parseNewTask(body: unknown): NewTask | string[] {
  if (typeof body !== "object" || body === null || Array.isArray(body)) return ["body must be a JSON object"];
  const input = body as Record<string, unknown>;
  const title = typeof input.title === "string" ? input.title.trim() : "";
  const priority = input.priority ?? "normal";
  const issues: string[] = [];
  if (title.length < 3) issues.push("title too short");
  if (!PRIORITIES.some((p) => p === priority)) issues.push("bad priority");
  if (issues.length > 0) return issues;
  return { title, priority: priority as Priority };
}

