function handle(rawBody: string): number {
  let body: unknown;
  try {
    body = JSON.parse(rawBody);
  } catch {
    return 400;
  }
  if (typeof body !== "object" || body === null || Array.isArray(body)) return 422;
  if (!("title" in body) || typeof body.title !== "string") return 422;
  return 201;
}

